// node tools/build-bundle.mjs   - turns registry/libraries.json (and, when it exists,
// registry/libraries.signed.json) into src/registry-bundle.js, which the Worker imports.
//
// WHY A GENERATED FILE. The registry must reach the client BYTE FOR BYTE (the signature is over the
// bytes), and a JSON import is parsed and re-serialised by the bundler. A string constant is not.
// The generated file is committed; test/bundle.test.mjs fails when it is out of date with the
// registry, and tools/predeploy.mjs refuses to deploy while it is.
//
// The build refuses (exit 1) a registry that does not validate, and a signed envelope whose
// payload is not exactly the registry bytes. When LINKS_PUBKEY_HEX (64 hex) is set it also verifies
// the signature; without it only the structure and the payload are checked and it says so.
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { validateRegistryText } from '../src/validate.js';
import { parseEnvelope, verifyEnvelope } from './envelope.mjs';

const here = fileURLToPath(new URL('.', import.meta.url));
export const REGISTRY_PATH = `${here}../registry/libraries.json`;
export const SIGNED_PATH = `${here}../registry/libraries.signed.json`;
export const BUNDLE_PATH = `${here}../src/registry-bundle.js`;

// -> { source, problems } ; problems is [] when everything checks out.
export function render(registryText, signedText, pubkeyHex = null) {
  const problems = [];
  const v = validateRegistryText(registryText);
  if (!v.ok) problems.push(...v.errors.map((e) => `registry: ${e}`));
  if (signedText !== null) {
    const p = parseEnvelope(signedText);
    if (!p.ok) {
      problems.push(`signed envelope: ${p.error}`);
    } else if (!p.payload.equals(Buffer.from(registryText, 'utf8'))) {
      problems.push('signed envelope: its payload is not exactly registry/libraries.json (re-sign after every edit)');
    } else if (pubkeyHex) {
      if (!/^[0-9a-f]{64}$/.test(pubkeyHex)) problems.push('LINKS_PUBKEY_HEX must be 64 lower-case hex characters');
      else {
        const r = verifyEnvelope(signedText, [Buffer.from(pubkeyHex, 'hex')]);
        if (!r.ok) problems.push(`signed envelope: ${r.error}`);
      }
    }
  }
  const source = `// GENERATED by tools/build-bundle.mjs from registry/libraries.json - do not edit by hand.
// The registry text is kept as one string so it is served byte for byte.
export const REGISTRY_TEXT = ${JSON.stringify(registryText)};
export const SIGNED_TEXT = ${signedText === null ? 'null' : JSON.stringify(signedText)};
`;
  return { source, problems };
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const registryText = readFileSync(REGISTRY_PATH, 'utf8');
  const signedText = existsSync(SIGNED_PATH) ? readFileSync(SIGNED_PATH, 'utf8') : null;
  const pub = process.env.LINKS_PUBKEY_HEX || null;
  const { source, problems } = render(registryText, signedText, pub);
  if (problems.length) {
    console.error('NOT BUILT:');
    for (const p of problems) console.error(`  - ${p}`);
    process.exit(1);
  }
  writeFileSync(BUNDLE_PATH, source, 'utf8');
  console.log(`wrote src/registry-bundle.js (${registryText.length} registry characters; signed envelope ${signedText === null ? 'ABSENT - /v1/libraries.signed.json will answer 404' : pub ? 'verified against LINKS_PUBKEY_HEX' : 'structure and payload checked, signature NOT verified (set LINKS_PUBKEY_HEX to verify)'})`);
}
